        const stack = [];
        board[r][c] = "S";
        stack.push([r, c]);
        while (stack.length) {
            [r, c] = stack.pop();
            for (const [dr, dc] of directions) {
                const nr = r + dr;
                const nc = c + dc;
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] === "O") {
                    board[nr][nc] = "S";
                    stack.push([nr, nc]);
                }
            }
        }
    };

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const onBorder = r === 0 || r === rows - 1 || c === 0 || c === cols - 1;
            if (onBorder && board[r][c] === "O") {
                markSafe(r, c);
            }
        }
    }

